//! Real-checkpoint waveform parity for #46.
//!
//! The large temporary fixture is generated by
//! `tools/parity/nanocodec/dump_reference.py` from the pinned official NeMo
//! `CausalHiFiGANDecoder`; it is intentionally not committed.

use std::fs;
use std::io::{Cursor, Read};

use vokra_models::nanocodec::{
    CausalHifiGan, CausalHifiGanConfig, CausalHifiGanConv1dWeights,
    CausalHifiGanConvTranspose1dWeights, CausalHifiGanHalfSnakeWeights,
    CausalHifiGanResidualBlockWeights, CausalHifiGanStageWeights, CausalHifiGanWeights,
};

const FIXTURE_ENV: &str = "VOKRA_NANOCODEC_PARITY_FIXTURE";
const MAGIC: &[u8; 8] = b"VKNCHP01";
const FORMAT_VERSION: u32 = 2;
const NEMO_SPEECH_COMMIT: &str = "4fcff72febec9395fdbd4bfa0747bfda2ecd3cef";
const CHECKPOINT_ID: &str = "nvidia/nemo-nano-codec-22khz-0.6kbps-12.5fps";
const CHECKPOINT_REVISION: &str = "5c8e22ed763c14d81337fbe6ca74062f3d10f7e5";
const CHECKPOINT_SHA256: &str = "bd5883099d0c74ceda760b6b7a1600b86da4d8a02531c9c282679951dcb08870";

// Pre-registered before the first real-checkpoint measurement. These bounds
// cover f32 accumulation and at-most-ULP scalar-sine differences, while staying
// below one 16-bit PCM quantization step in RMS. Investigate failures; never
// relax from an observed failing run.
const MAX_ABS_BOUND: f32 = 2.0e-4;
const RMSE_BOUND: f64 = 2.0e-5;

struct Reader<'a> {
    cursor: Cursor<&'a [u8]>,
}

impl<'a> Reader<'a> {
    fn new(bytes: &'a [u8]) -> Self {
        Self {
            cursor: Cursor::new(bytes),
        }
    }

    fn exact<const N: usize>(&mut self) -> [u8; N] {
        let mut bytes = [0u8; N];
        self.cursor
            .read_exact(&mut bytes)
            .expect("fixture truncated");
        bytes
    }

    fn u32(&mut self) -> u32 {
        u32::from_le_bytes(self.exact())
    }

    fn usize(&mut self) -> usize {
        usize::try_from(u64::from_le_bytes(self.exact())).expect("fixture usize overflow")
    }

    fn string(&mut self) -> String {
        let len = self.usize();
        let mut bytes = vec![0u8; len];
        self.cursor
            .read_exact(&mut bytes)
            .expect("fixture truncated");
        String::from_utf8(bytes).expect("fixture string is not UTF-8")
    }

    fn usizes(&mut self) -> Vec<usize> {
        let len = self.usize();
        (0..len).map(|_| self.usize()).collect()
    }

    fn f32s(&mut self) -> Vec<f32> {
        let len = self.usize();
        (0..len).map(|_| f32::from_le_bytes(self.exact())).collect()
    }

    fn is_eof(&self) -> bool {
        self.cursor.position() as usize == self.cursor.get_ref().len()
    }
}

fn half_snake(reader: &mut Reader<'_>) -> CausalHifiGanHalfSnakeWeights {
    CausalHifiGanHalfSnakeWeights {
        alpha: reader.f32s(),
        alpha_inv: reader.f32s(),
    }
}

fn conv(reader: &mut Reader<'_>) -> CausalHifiGanConv1dWeights {
    CausalHifiGanConv1dWeights {
        weight: reader.f32s(),
        bias: reader.f32s(),
    }
}

struct Fixture {
    nemo_source: String,
    torch_version: String,
    cpu_capability: String,
    execution_environment: String,
    config: CausalHifiGanConfig,
    weights: CausalHifiGanWeights,
    features: Vec<f32>,
    expected_pcm: Vec<f32>,
}

fn parse_fixture(bytes: &[u8]) -> Fixture {
    let mut reader = Reader::new(bytes);
    assert_eq!(&reader.exact::<8>(), MAGIC);
    assert_eq!(reader.u32(), FORMAT_VERSION);
    assert_eq!(reader.string(), NEMO_SPEECH_COMMIT);
    let nemo_source = reader.string();
    let torch_version = reader.string();
    let cpu_capability = reader.string();
    let execution_environment = reader.string();
    let checkpoint_id = reader.string();
    let checkpoint_revision = reader.string();
    let checkpoint_sha256 = reader.string();
    assert!(
        nemo_source.contains("github.com/NVIDIA-NeMo/Speech"),
        "unexpected NeMo source: {nemo_source}"
    );
    assert_eq!(checkpoint_id, CHECKPOINT_ID);
    assert_eq!(checkpoint_revision, CHECKPOINT_REVISION);
    assert_eq!(checkpoint_sha256, CHECKPOINT_SHA256);
    assert!(!torch_version.is_empty());
    assert!(!cpu_capability.is_empty());
    assert!(!execution_environment.is_empty());

    let config = CausalHifiGanConfig {
        input_dim: reader.usize(),
        base_channels: reader.usize(),
        frame_hop: reader.usize(),
        upsample_rates: reader.usizes(),
        input_kernel_size: reader.usize(),
        output_kernel_size: reader.usize(),
        resblock_kernel_sizes: reader.usizes(),
        resblock_dilations: reader.usizes(),
    };
    let pre_conv = conv(&mut reader);
    let mut stages = Vec::with_capacity(config.upsample_rates.len());
    for _ in &config.upsample_rates {
        let activation = half_snake(&mut reader);
        let upsample = CausalHifiGanConvTranspose1dWeights {
            weight: reader.f32s(),
            bias: reader.f32s(),
        };
        let mut residual_branches = Vec::with_capacity(config.resblock_kernel_sizes.len());
        for _ in &config.resblock_kernel_sizes {
            let mut blocks = Vec::with_capacity(config.resblock_dilations.len());
            for _ in &config.resblock_dilations {
                blocks.push(CausalHifiGanResidualBlockWeights {
                    input_activation: half_snake(&mut reader),
                    input_conv: conv(&mut reader),
                    skip_activation: half_snake(&mut reader),
                    skip_conv: conv(&mut reader),
                    dilation: reader.usize(),
                });
            }
            residual_branches.push(blocks);
        }
        stages.push(CausalHifiGanStageWeights {
            activation,
            upsample,
            residual_branches,
        });
    }
    let weights = CausalHifiGanWeights {
        pre_conv,
        stages,
        post_activation: half_snake(&mut reader),
        post_conv: conv(&mut reader),
    };
    let features = reader.f32s();
    let expected_pcm = reader.f32s();
    assert!(reader.is_eof(), "fixture has trailing bytes");
    Fixture {
        nemo_source,
        torch_version,
        cpu_capability,
        execution_environment,
        config,
        weights,
        features,
        expected_pcm,
    }
}

#[test]
fn real_nemo_checkpoint_waveform_parity() {
    let Some(path) = std::env::var_os(FIXTURE_ENV) else {
        eprintln!(
            "SKIP: set {FIXTURE_ENV} to the temporary fixture generated by tools/parity/nanocodec/dump_reference.py"
        );
        return;
    };
    let bytes = fs::read(&path).expect("read NanoCodec parity fixture");
    let fixture = parse_fixture(&bytes);
    eprintln!(
        "NanoCodec reference environment: nemo_source={}, torch={}, cpu_capability={}, {}",
        fixture.nemo_source,
        fixture.torch_version,
        fixture.cpu_capability,
        fixture.execution_environment
    );
    let decoder = CausalHifiGan::new(fixture.config, fixture.weights)
        .expect("bind real NeMo decoder tensors");
    let actual = decoder
        .decode_all(&fixture.features)
        .expect("decode real features");
    assert_eq!(actual.len(), fixture.expected_pcm.len());

    let mut max_abs = 0.0f32;
    let mut squared_error = 0.0f64;
    for (&got, &want) in actual.iter().zip(&fixture.expected_pcm) {
        let error = (got - want).abs();
        max_abs = max_abs.max(error);
        squared_error += f64::from(error) * f64::from(error);
    }
    let rmse = (squared_error / actual.len() as f64).sqrt();
    eprintln!(
        "NanoCodec NeMo parity: {CHECKPOINT_ID}@{CHECKPOINT_REVISION}, samples={}, max_abs={max_abs:.9e}, rmse={rmse:.9e}",
        actual.len()
    );
    assert!(
        max_abs <= MAX_ABS_BOUND,
        "max_abs {max_abs:.9e} > pre-registered {MAX_ABS_BOUND:.9e}"
    );
    assert!(
        rmse <= RMSE_BOUND,
        "rmse {rmse:.9e} > pre-registered {RMSE_BOUND:.9e}"
    );

    // The same real tensors also pin the issue's bit-identical chunking
    // contract independently of the tiny unit fixture.
    let frames = fixture.features.len() / decoder.expected_feature_dim();
    let mut state = decoder.state(1).expect("one-frame state");
    let mut streamed = vec![0.0f32; actual.len()];
    for frame in 0..frames {
        let feature_start = frame * decoder.expected_feature_dim();
        let pcm_start = frame * decoder.frame_hop();
        decoder
            .decode_into(
                &mut state,
                &fixture.features[feature_start..feature_start + decoder.expected_feature_dim()],
                &mut streamed[pcm_start..pcm_start + decoder.frame_hop()],
            )
            .expect("stream real frame");
    }
    assert_eq!(actual, streamed, "real checkpoint full != frame streaming");
}
